-- Real profiles, disposable messages and reports. Everything is rolled back.
begin;
select set_config('request.jwt.claim.sub',(select id::text from public.profiles where full_name='Adrian Mora' and active limit 1),true);
set local role authenticated;
do $$
declare reporter uuid:=auth.uid();reviewer uuid;op uuid;supervisor uuid;o public.field_observations%rowtype;other_obs uuid;op_obs uuid;mid bigint;reply bigint;later bigint;retry uuid:=gen_random_uuid();context jsonb;before_ai integer;original_status text;failed boolean;
begin
 select * into strict o from public.field_observations where reported_by=reporter and assigned_manager_id<>reporter order by submitted_at desc limit 1;
 reviewer:=o.assigned_manager_id;original_status:=o.status;
 select id,corporate_manager_id into strict op,supervisor from public.profiles where role='operator' and active and full_name not like '[MOC]%' order by created_at limit 1;
 select count(*) into before_ai from public.observation_ai_memory where observation_id=o.id;
 context:=public.observation_conversation_context(o.id);
 if not (context->>'can_send')::boolean or (context->>'assigned_manager_id')::uuid<>reviewer then raise exception 'Reporter context is incorrect';end if;
 mid:=public.send_field_observation_message(o.id,'[QA rollback] Please clarify the location',retry);
 if public.send_field_observation_message(o.id,'[QA rollback] Please clarify the location',retry)<>mid then raise exception 'Retry duplicated message';end if;
 if (select count(*) from public.field_observation_messages where observation_id=o.id and client_message_id=retry)<>1 then raise exception 'Duplicate message rows';end if;
 failed:=false;begin perform public.send_field_observation_message(o.id,'Different text',retry);exception when others then failed:=true;end;if not failed then raise exception 'Retry ID accepted for different text';end if;
 other_obs:=(public.submit_field_observation(gen_random_uuid(),o.business_unit_id,o.asset_id,'equipment','[QA rollback] separate conversation','normal')->>'observation_id')::uuid;
 failed:=false;begin perform public.send_field_observation_message(other_obs,'[QA rollback] Please clarify the location',retry);exception when others then failed:=true;end;if not failed then raise exception 'Retry ID crossed observations';end if;
 if exists(select 1 from public.field_observation_messages where observation_id=other_obs) then raise exception 'Messages mixed across observations';end if;
 failed:=false;begin update public.field_observation_messages set body='Rewrite evidence' where id=mid;exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Client can edit evidence';end if;
 failed:=false;begin delete from public.field_observation_messages where id=mid;exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Client can delete evidence';end if;
 failed:=false;begin insert into public.field_observation_messages(observation_id,author_id,author_name,author_role,body,client_message_id) values(o.id,reviewer,'Forged','reviewer','Not the actor',gen_random_uuid());exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Client can forge an author';end if;
 perform set_config('request.jwt.claim.sub',reviewer::text,true);
 if not exists(select 1 from public.field_observation_messages where id=mid and author_id=reporter and author_role='reporter') then raise exception 'Reviewer cannot read reporter message';end if;
 if (select count(*) from public.notifications where observation_id=o.id and notification_type='observation_message' and dedupe_key='observation-message:'||mid)<>1 then raise exception 'Message notification missing or duplicated';end if;
 if not exists(select 1 from public.field_observation_chat_updates where observation_id=o.id and has_updates) then raise exception 'Reviewer unread badge missing';end if;
 reply:=public.send_field_observation_message(o.id,'[QA rollback] Use the north shelf',gen_random_uuid());
 perform public.mark_observation_messages_seen(o.id,mid);
 if exists(select 1 from public.field_observation_chat_updates where observation_id=o.id and has_updates) then raise exception 'Read badge not cleared';end if;
 perform set_config('request.jwt.claim.sub',reporter::text,true);
 if not exists(select 1 from public.field_observation_messages where id=reply and author_id=reviewer and author_role='reviewer') then raise exception 'Reporter cannot read reviewer reply';end if;
 later:=public.send_field_observation_message(o.id,'[QA rollback] Confirmed',gen_random_uuid());
 perform set_config('request.jwt.claim.sub',reviewer::text,true);
 perform public.mark_observation_messages_seen(o.id,mid);
 if not exists(select 1 from public.field_observation_chat_updates where observation_id=o.id and has_updates) then raise exception 'Old read cursor hid a new message';end if;
 perform public.mark_observation_messages_seen(o.id,later);
 if exists(select 1 from public.field_observation_chat_updates where observation_id=o.id and has_updates) then raise exception 'Latest read cursor did not clear messages';end if;
 perform set_config('request.jwt.claim.sub',op::text,true);
 if exists(select 1 from public.field_observation_messages where observation_id=o.id) then raise exception 'Unrelated operator can read the chat';end if;
 failed:=false;begin perform public.observation_conversation_context(o.id);exception when others then failed:=true;end;if not failed then raise exception 'Private participants exposed to unrelated operator';end if;
 failed:=false;begin perform public.send_field_observation_message(o.id,'[QA rollback] unrelated',gen_random_uuid());exception when others then failed:=true;end;if not failed then raise exception 'Unrelated operator can send';end if;
 op_obs:=(public.submit_field_observation(gen_random_uuid(),o.business_unit_id,o.asset_id,'equipment','[QA rollback] operator conversation','normal')->>'observation_id')::uuid;
 perform public.send_field_observation_message(op_obs,'[QA rollback] Operator question',gen_random_uuid());
 perform set_config('request.jwt.claim.sub',supervisor::text,true);
 perform public.send_field_observation_message(op_obs,'[QA rollback] Supervisor reply',gen_random_uuid());
 perform set_config('request.jwt.claim.sub',reviewer::text,true);
 context:=public.observation_conversation_context(op_obs);
 if (context->>'can_send')::boolean then raise exception 'Corporate observer incorrectly gained reply permission';end if;
 failed:=false;begin perform public.send_field_observation_message(op_obs,'[QA rollback] Not a participant',gen_random_uuid());exception when others then failed:=true;end;if not failed then raise exception 'Corporate observer can join bilateral chat';end if;
 if (select status from public.field_observations where id=o.id)<>original_status then raise exception 'Chat changed observation status';end if;
 if (select count(*) from public.observation_ai_memory where observation_id=o.id)<>before_ai then raise exception 'Chat changed accepted AI memory';end if;
 -- Closure keeps the conversation available, without reopening the report.
 perform public.close_field_observation(other_obs,'closed_no_action','[QA rollback] Close test report');
 perform set_config('request.jwt.claim.sub',reporter::text,true);
 perform public.send_field_observation_message(other_obs,'[QA rollback] Post-closure clarification',gen_random_uuid());
 if (select status from public.field_observations where id=other_obs)<>'closed_no_action' then raise exception 'Chat reopened a closed report';end if;
 if has_function_privilege('anon','public.send_field_observation_message(uuid,text,uuid)','execute') or has_table_privilege('anon','public.field_observation_messages','select') then raise exception 'Anonymous access introduced';end if;
end$$;
rollback;
